-- PostgreSQL logical schema. Synthetic exception cases are retained in input tables;
-- run src/cli.js validate for anomaly-aware validation.
CREATE TABLE claimants (claimant_id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, created_at DATE NOT NULL);
CREATE TABLE policies (policy_id TEXT PRIMARY KEY, claimant_id TEXT NOT NULL REFERENCES claimants, policy_type TEXT NOT NULL CHECK(policy_type IN ('auto','home','health')), effective_from DATE NOT NULL, effective_to DATE NOT NULL, lifecycle_state TEXT NOT NULL, coverage_limit NUMERIC(12,2) NOT NULL CHECK(coverage_limit>=0));
CREATE TABLE incidents (incident_id TEXT PRIMARY KEY, incident_type TEXT NOT NULL, occurred_at DATE NOT NULL, reported_at DATE NOT NULL CHECK(reported_at>=occurred_at), location TEXT NOT NULL, narrative TEXT NOT NULL);
CREATE TABLE providers (provider_id TEXT PRIMARY KEY, name TEXT NOT NULL, provider_type TEXT NOT NULL, tax_id TEXT NOT NULL UNIQUE, address TEXT NOT NULL, created_at DATE NOT NULL);
CREATE TABLE claims (claim_id TEXT PRIMARY KEY, claimant_id TEXT NOT NULL REFERENCES claimants, policy_id TEXT NOT NULL, incident_id TEXT NOT NULL REFERENCES incidents, filed_at DATE NOT NULL, status TEXT NOT NULL CHECK(status IN ('submitted','under_review','approved','partially_approved','denied','paid')), claimed_amount NUMERIC(12,2) NOT NULL CHECK(claimed_amount>=0), approved_amount NUMERIC(12,2) NOT NULL CHECK(approved_amount>=0), currency CHAR(3) NOT NULL);
-- policy_id is deliberately unconstrained here so the explicitly labelled invalid-policy exception can be exported.
CREATE TABLE invoices (invoice_record_id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, provider_id TEXT NOT NULL REFERENCES providers, claim_id TEXT NOT NULL REFERENCES claims, issued_at DATE NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), currency CHAR(3) NOT NULL, lifecycle_state TEXT NOT NULL);
CREATE TABLE payments (payment_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims, invoice_record_id TEXT NOT NULL REFERENCES invoices, paid_at DATE NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), currency CHAR(3) NOT NULL, status TEXT NOT NULL);
CREATE TABLE relationship_edges (edge_id TEXT PRIMARY KEY, source_type TEXT NOT NULL CHECK(source_type='claimant'), source_id TEXT NOT NULL REFERENCES claimants, target_type TEXT NOT NULL CHECK(target_type='claimant'), target_id TEXT NOT NULL REFERENCES claimants, relationship_type TEXT NOT NULL, confidence NUMERIC(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), effective_from DATE NOT NULL, effective_to DATE, source TEXT NOT NULL, CHECK(source_id<>target_id));
CREATE TABLE fraud_indicators (indicator_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims, indicator_type TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('low','medium','high')), evidence TEXT NOT NULL, created_at DATE NOT NULL);
CREATE TABLE investigations (investigation_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims, assigned_role TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','in_review','closed')), priority TEXT NOT NULL, opened_at DATE NOT NULL, closed_at DATE, outcome TEXT);
CREATE TABLE claim_state_events (event_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims, prior_state TEXT, next_state TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE payment_state_events (event_id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments, prior_state TEXT, next_state TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE claim_providers (claim_id TEXT NOT NULL REFERENCES claims, provider_id TEXT NOT NULL REFERENCES providers, service_role TEXT NOT NULL CHECK(service_role IN ('repairer','medical','tow','property_restoration')), effective_from DATE NOT NULL, effective_to DATE, PRIMARY KEY(claim_id,provider_id,service_role,effective_from));
-- Evaluation-only labels. Do not join claim_issues into operational model features.
CREATE TABLE claim_issues (issue_id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims, issue_type TEXT NOT NULL, ground_truth_label TEXT NOT NULL, detected_at TIMESTAMPTZ NOT NULL, resolution_state TEXT NOT NULL);
